
-- Project: Northwind SQL Business Analysis
-- File: 11_order_value_analysis.sql
-- Business Questions:
-- 1. What is the revenue generated by each order?
-- 2. What are the average, highest, and lowest order values?
-- SQL Concepts: JOIN, SUM, COUNT, AVG, MAX, MIN,
-- GROUP BY, ORDER BY, CTE, ROUND

-- Query 1: Revenue for each order

SELECT
    o.orderid,
    o.customerid,
    o.orderdate,
    COUNT(DISTINCT od.productid) AS distinct_products,
    SUM(od.quantity) AS total_units,
    ROUND(
        SUM(od.unitprice * od.quantity * (1 - od.discount))::NUMERIC,
        2
    ) AS order_revenue
FROM orders AS o
JOIN order_details AS od
    ON o.orderid = od.orderid
GROUP BY
    o.orderid,
    o.customerid,
    o.orderdate
ORDER BY order_revenue DESC;


-- Query 2: Average, highest, and lowest order value

WITH order_revenue AS (
    SELECT
        o.orderid,
        SUM(
            od.unitprice * od.quantity * (1 - od.discount)
        ) AS revenue
    FROM orders AS o
    JOIN order_details AS od
        ON o.orderid = od.orderid
    GROUP BY o.orderid
)
SELECT
    COUNT(*) AS total_orders,
    ROUND(AVG(revenue)::NUMERIC, 2) AS average_order_value,
    ROUND(MAX(revenue)::NUMERIC, 2) AS highest_order_value,
    ROUND(MIN(revenue)::NUMERIC, 2) AS lowest_order_value
FROM order_revenue;
